/**
 * TalkCommands.js — what you can ORDER or ASK a villager in plain words (the author: «рыцари не понимают команд…
 * нужно ПОСТОЯННОЕ живое взаимодействие и ОГРОМНОЕ количество разных команд… если он что-то не может — отвечает,
 * что не может, а не молчит»).
 *
 * Pure (no THREE / DOM): one table, `COMMANDS`, says for every command
 *   - how it is said (many words, forms, slang — rules read it at once, no neural net),
 *   - WHO can do it (`who`) and who must be the king for it (`rank`),
 *   - HOW it is done (`do`: a pose, a walk, a fight… — carried out by src/game/VillagerCommands.js),
 *   - WHAT the villager says when he can't (`reason` → REASONS, per kind of person) and when he can (acks).
 * Like IMPERIUS_TARGETS: every role has a row for every command (tests/unit/talk-commands.test.js), so a new role or a
 * new command is never silently ignored: «не могу» is an answer too.
 *
 * Group words («все», «вы двое», «левый», «ближайший», names) → `scope`; «он / тот / вон тот» → `target.ref`.
 */

import { normalize } from '../game/VillagerBrain.js';

const L = '(?<![а-яa-z0-9])';
const R = '(?![а-яa-z0-9])';

/** Everybody a command may be given to: castle people, wizards, the ships' crew. */
export const COMMAND_ROLES = ['knight', 'advisor', 'king', 'merchant', 'seller', 'builder', 'farmer', 'wizard', 'sailor'];
const MIL = new Set(['knight', 'advisor', 'sailor']); // those used to orders
const ALL = COMMAND_ROLES;
const NOT_KING = ALL.filter((r) => r !== 'king');
const FIGHTERS = ['knight']; // those who fight by an order
const CASTERS = ['wizard'];

/** The kind of person a role is when a line is chosen: 'knight' | 'adv' | 'king' | 'wiz' | 'sea' | 'civ'. */
export function kindOf(role, ctx = {}) {
    if (ctx.wizard || role === 'wizard') return 'wiz';
    if (role === 'knight') return 'knight';
    if (role === 'advisor') return 'adv';
    if (role === 'king') return 'king';
    if (SEA_ROLES.has(role)) return 'sea';
    return 'civ';
}

const SEA_ROLES = new Set(['sailor', 'captain', 'boatswain', 'blackbeard', 'skeleton']);
const normRole = (role, ctx = {}) => (ctx.wizard ? 'wizard' : SEA_ROLES.has(role) ? 'sailor' : role === 'seller' || role === 'merchant' || role === 'builder' || role === 'farmer' || role === 'knight' || role === 'advisor' || role === 'king' || role === 'sailor' ? role : COMMAND_ROLES.includes(role) ? role : 'farmer');

