const pickFrom = (a, rng = Math.random) => a[Math.floor(rng() * a.length) % a.length];

// ------------------------------------------------------------------ the table

/**
 * id → { cat, re, who, rank, do, reason, ack, group }
 *  cat:  body | move | combat | things | talk
 *  re:   RegExp source(s) over normalized text (any matches)
 *  who:  roles that can do it; rank: 'king' → in the castle's guard only the king (the player who owns it) commands it
 *  do:   how it is carried out ('pose:crouch', 'walk:come', 'fight:spar', 'say:hp'…) — VillagerCommands.js
 *  reason: REASONS key for the others (and `no`: own lines per kind)
 *  ack:  the short word in advance (or null: a pose speaks for itself)
 */
const C = {};
const def = (id, cat, re, o) => { C[id] = { id, cat, re: [].concat(re).map((s) => new RegExp(s)), who: NOT_KING, rank: null, group: false, ack: 'ok', reason: 'notDone', ...o }; };

