export const COMMANDS = C;
export const COMMAND_IDS = Object.keys(C);

// ------------------------------------------------------------------ who can

const KING_LINES = ['Ты приказываешь мне? Королю?!', 'Здесь приказываю я.', 'Дерзость! Я здесь правитель.'];

/**
 * May this person do it — and if not, what does he say?
 * @param {string} id a command id
 * @param {string} role villager role
 * @param {{playerIsKing?:boolean, wizard?:boolean, female?:boolean}} [ctx]
 * @returns {{ok:true, ack:string|null} | {ok:false, why:string, line:string}}
 */
export function canDo(id, role, ctx = {}, rng = Math.random) {
    const c = C[id];
    if (!c) return { ok: false, why: 'unknown', line: 'Не понял, чего ты хочешь.' };
    const r = normRole(role, ctx);
    const k = kindOf(role, ctx);
    const no = (why, lines) => ({ ok: false, why, line: pickFrom(lines, rng) });
    // (the king of the castle takes no orders from a stranger — talk, yes)
    if (r === 'king' && !ctx.playerIsKing && c.cat !== 'talk' && c.cat !== 'body') return no('king', KING_LINES);
    if (r === 'king' && !ctx.playerIsKing && c.cat === 'body' && !['nod', 'turn_me', 'wave', 'look_there'].includes(id)) return no('king', KING_LINES);
    if (c.builderOk && r === 'builder') return no('cant', REASONS.notBuilder.civ.concat(['Тут нужны материалы и время — не сразу.']));
    if (!c.who.includes(r)) {
        const own = c.no?.[k] || (r === 'wizard' ? c.wizNo : null);
        if (own) return no('cant', own);
        // (a knight asked for a soldier's trade by a stranger is «rank»; a civilian asked to fight — «peaceful»)
        const rs = REASONS[c.reason] || REASONS.notDone;
        return no('cant', rs[k] || rs.civ);
    }
    // (rank: the guard's orders — the king only)
    if (c.rank === 'king' && !ctx.playerIsKing) {
        const rs = REASONS.rank;
        return no('rank', rs[k] || rs.civ);
    }
    if (r === 'advisor' && c.cat === 'combat' && !['stop_fight', 'spare', 'shield_down'].includes(id)) return no('cant', REASONS.rank.adv);
    return { ok: true, ack: c.ack };
}

/** The table, one row per command: role → 'ok' | 'rank' | 'no:<reason>' — for the docs and the tests. */
export function commandTable(playerIsKing = false) {
    return COMMAND_IDS.map((id) => {
        const row = { id, cat: C[id].cat, do: C[id].do };
        for (const role of COMMAND_ROLES) {
            const r = canDo(id, role, { playerIsKing }, () => 0);
            row[role] = r.ok ? 'ok' : r.why === 'rank' ? 'rank' : `no:${r.why}`;
        }
        return row;
    });
}

// ------------------------------------------------------------------ reading the words

/** How many «you» the words address, or which of them: «все», «вы двое», «левый», «ближайший». */
const SCOPE_NUM = [
    [/(^| )(вы )?(двое|оба|обе|вдвоем|вдвоём|парочка|пара)( |$)|(^| )два (рыцаря|стражника|воина|солдата|человека)( |$)|(^| )двое( |$)/, 2],
    [/(^| )(вы )?(трое|втроем|втроём|тройка)( |$)|(^| )три (рыцаря|стражника|воина|солдата|человека)( |$)/, 3],
    [/(^| )(вы )?(четверо|вчетвером|четверка|четвёрка)( |$)|(^| )четыре (рыцаря|стражника|воина|солдата|человека)( |$)/, 4],
    [/(^| )(вы )?(пятеро|впятером|пятерка|пятёрка)( |$)|(^| )пять (рыцарей|стражников|воинов|солдат|человек)( |$)/, 5],
    [/(^| )(вы )?(шестеро|вшестером)( |$)|(^| )шесть (рыцарей|стражников|воинов|солдат|человек)( |$)/, 6],
];
const SCOPE_ALL = /(^| )(все|всем|вы все|всех|всё|рыцари|рыцарей|рыцарям|стража|стражники|стражу|стражей|войско|армия|армию|дружина|дружину|отряд|взвод|ребята|парни|братья|братцы|воины|солдаты|гвардия|гвардейцы|вы)( |$)/;
const SCOPE_LEFT = /(^| )(левый|левого|левому|левым|слева|тот что слева|который слева|кто слева|что слева|левее|левая|левую)( |$)/;
const SCOPE_RIGHT = /(^| )(правый|правого|правому|правым|справа|тот что справа|который справа|кто справа|что справа|правее|правая|правую)( |$)/;
const SCOPE_NEAR = /(^| )(ближайший|ближайшего|ближайшему|ближайшим|ближний|ближнего|ближняя|ближайшая|ближайшую|тот что рядом|который рядом|кто рядом|что рядом|ближе всех|поближе|самый близкий|самого близкого|рядом стоящий|рядом стоящего|стоящий рядом|стоящего рядом)( |$)/;
const SCOPE_REST = /(^| )(остальные|остальных|остальным|все остальные|прочие|прочих|другие|другим|других)( |$)/;
/** «его / ним / того / вон тот»: an object pointed at, looked at, or named. */
const REF_POINT = /(^| )(его|ее|их|ним|ней|ними|того|эту|этого|этому|этим|тем|той|тех|вон тот|вон этот|вон того|вон тем|вон та|вон ту|вон с тем|вон с тем рыцарем|этот|тот|эта|та|он|она|они)( |$)/;
const DEADLY = /(насмерть|на смерть|до смерти|до конца|по настоящему|по-настоящему|всерьез|всерьёз|взаправду|взаправду|не шутя|жестоко|без пощады|на убой|убить|убей|убейте|убивайте|не щадя|без жалости|по взрослому|по-взрослому)/;
const FRIENDLY = /(понарошку|не всерьез|не всерьёз|тренировочн|тренировк|шутя|в шутку|не насмерть|не до смерти|без крови|без ран|чуть чуть|чуть-чуть|аккуратно|осторожно|для виду|для вида|показательно|покажите|покажи)/;
const FORM = [
    [/(в )?(колонн|затылок|по одному)/, 'column'],
    [/(в )?(круг|кольц|окружи|окружайт|окружить|хоровод)/, 'circle'],
    [/(клин|клином)/, 'wedge'],
    [/(стен\S* щит|щит к щиту|плечом к плечу|стеной щитов)/, 'shields'],
    [/(в )?(две шеренги|двумя шеренгами|парами|по двое|в два ряда)/, 'two'],
    [/(в )?(шеренг|линию|линия|ряд|цепь|цепью|шеренгой|строй|построиться|построй|стройс)/, 'line'],
];
const PACE = [
    [/(красться|крадись|крадитесь|тихо|тихонько|пригнувшись|подкрад)/, 'sneak'],
    [/(бегом|беги|бегите|быстр|живо|живее|рысью|поторопи|ускорь|ходу)/, 'run'],
    [/(шагом|спокойно|медленн|не спеша|не торопись|не торопитесь|не беги|не бегите|потише)/, 'walk'],
];

/**
 * Reads a command in plain words (no net).
 * @returns {null | {id:string, cat:string, args:{scope:{kind:string,n?:number}, target:{ref:string,name?:string}, mode:string, form?:string, pace?:string}}}
 */
export function parseCommand(text, opts = {}) {
    const t = normalize(text);
    if (!t) return null;
    const words = t.split(' ');
    // (words that mean something else to the old reader — an army order of the king, a dismissal — are not read here)
    let found = null, bestLen = 0;
    for (const id of COMMAND_IDS) {
        const c = C[id];
        if (words.length < (c.minWords || 1)) continue;
        const res = c.strict ? c.strict.map((x) => new RegExp(x)) : c.re;
        let m = null;
        for (const re of res) { m = re.exec(t); if (m) break; }
        if (!m || (c.not && c.not.test(t))) continue;
        // (a command stands at the head of the phrase («рыцарь, присядь», «эй, сразитесь друг с другом») and the phrase is short:
        // a long ramble that happens to contain «погоди» or «хватит» is a talk, not an order)
        const before = t.slice(0, m.index).trim().split(' ').filter(Boolean).length;
        if (before > 4 || words.length > (TINY.has(id) ? 3 : SOFT.has(id) ? 5 : 11)) continue;
        if (m[0].length > bestLen) { found = id; bestLen = m[0].length; } // (the longest words win: «встаньте в шеренгу» is a formation, not «встаньте»)
    }
    if (!found) return null;
    const c = C[found];
    const args = { scope: scopeOf(t), target: targetOf(t, opts.names || []), mode: DEADLY.test(t) ? 'deadly' : 'spar' };
    if (FRIENDLY.test(t) && !DEADLY.test(t)) args.mode = 'spar';
    if (c.do.startsWith('form:')) { args.form = FORM.find(([re]) => re.test(t))?.[1] || (found === 'surround' ? 'circle' : 'line'); }
    if (found === 'surround') args.form = 'circle';
    if (found === 'run' || found === 'walk' || found === 'sneak') args.pace = PACE.find(([re]) => re.test(t))?.[1] || c.do.slice(5);
    else { const pm = PACE.find(([re]) => re.test(t)); if (pm && c.cat === 'move') args.pace = pm[1]; }
    if (found === 'turn_dir') args.dir = /направо/.test(t) ? 'right' : /налево/.test(t) ? 'left' : 'back';
    if (found === 'look_there') args.dir = /направо/.test(t) ? 'right' : /налево/.test(t) ? 'left' : /назад/.test(t) ? 'back' : /вверх|небо/.test(t) ? 'up' : /вниз|землю/.test(t) ? 'down' : null;
    if (found === 'weapon_out' || found === 'weapon_away') args.weapon = true;
    if (c.group || args.scope.kind !== 'none') args.group = true;
    return { id: found, cat: c.cat, args };
}

/** Commands that are short words said alone: in a longer phrase they are ordinary talk («погоди, а где король?»). */
const SOFT = new Set(['wait', 'hold', 'repeat', 'come', 'run', 'walk', 'sneak', 'stop_fight', 'ask_sees', 'ask_hp', 'ask_role', 'laugh', 'nod', 'look_there', 'turn_dir', 'step_back', 'step_forward', 'sit', 'stand_up', 'lie', 'shield_down', 'take_item', 'put_down', 'bring', 'pick_up', 'give_item', 'fly', 'throw_it', 'attn', 'circle_me']);
/** … and these only as one to three words. */
const TINY = new Set(['wait', 'repeat', 'stop_fight', 'laugh', 'nod']);
/** Commands that mean something only while he is doing something (a fight, a pose): otherwise they are ordinary words. */
export const ONLY_ACTIVE = new Set(['stop_fight', 'shield_down', 'spare', 'stand_up', 'step_forward']);

export function scopeOf(t) {
    for (const [re, n] of SCOPE_NUM) if (re.test(t)) return { kind: 'n', n };
    if (SCOPE_LEFT.test(t) && !/(с|против) \S*(левым|левого)/.test(t)) return { kind: 'left' };
    if (SCOPE_RIGHT.test(t) && !/(с|против) \S*(правым|правого)/.test(t)) return { kind: 'right' };
    if (SCOPE_NEAR.test(t) && !/(с|против) \S*ближайш/.test(t)) return { kind: 'nearest' };
    if (SCOPE_REST.test(t)) return { kind: 'rest' };
    if (SCOPE_ALL.test(t)) return { kind: 'all' };
    return { kind: 'none' };
}

/** Whom «с ним» is about: a hand-pointed / looked-at one, a side, the nearest, a name. */
export function targetOf(t, names = []) {
    const after = (t.match(/(?:^| )(?:с|со|против|на|вон с|вон на) ([а-я]+(?: [а-я]+)?)$/) || [])[1] || t;
    if (/(со мной|со мною|против меня|меня)( |$)/.test(t)) return { ref: 'player' };
    for (const n of names) {
        const s = normalize(n);
        if (!s) continue;
        const stem = s.length > 4 ? s.slice(0, s.length - 1) : s;
        if (t.split(' ').some((w) => w.startsWith(stem) && w.length <= s.length + 3)) return { ref: 'name', name: n };
    }
    if (/(^| )(с|против|на|вон с|вон на|вон) (левым|левого|левому)/.test(t) || /(^| )(левого|левым)( |$)/.test(after)) return { ref: 'left' };
    if (/(^| )(с|против|на|вон с|вон на|вон) (правым|правого|правому)/.test(t) || /(^| )(правого|правым)( |$)/.test(after)) return { ref: 'right' };
    if (/ближайш/.test(after) || /ближайш(им|его|ему)/.test(t)) return { ref: 'nearest' };
    if (/(^| )(другим|другого|другому|другой|соседом|соседа|соседним|соседнего|вторым|второго)( |$)/.test(t)) return { ref: 'other' };
    if (REF_POINT.test(t) || /(этим|тем|тот|того|этого)/.test(t)) return { ref: 'point' };
    return { ref: 'none' };
}

// ------------------------------------------------------------------ the replies

/** The short word said at once to a command that was understood and will be done. [man, woman] or one string. */
export const COMMAND_ACKS = {
    knight: ['Есть!', 'Слушаюсь!', 'Так точно!', 'Будет исполнено!'],
    adv: ['Как прикажете.', 'Слушаюсь, Ваше Величество.', 'Сию минуту.'],
    sea: ['Есть!', 'Так точно!', 'Слушаюсь!'],
    wiz: ['Хорошо.', 'Как скажешь.', ['Пожалуйста.', 'Пожалуйста.']],
    civ: ['Хорошо!', 'Сейчас!', ['Понял!', 'Поняла!'], 'Ладно!', 'Как скажешь.'],
    king: ['Хм. Пусть будет так.'],
};
export const SHORT_ACKS = {
    knight: ['Есть!', 'Так точно!'], adv: ['Хорошо.'], sea: ['Есть!'], wiz: ['Хорошо.'], civ: ['Ладно!', 'Хорошо.'], king: ['Хм.'],
};

/** The word for a command (or null: the pose speaks). */
export function commandAck(id, role, ctx = {}, rng = Math.random, ready = null) {
    const c = C[id];
    if (!c || c.ack === null) return null;
    const k = kindOf(role, ctx);
    const pool = (c.ack === 'short' ? SHORT_ACKS : COMMAND_ACKS)[k] || COMMAND_ACKS.civ;
    const lines = pool.map((l) => (Array.isArray(l) ? l[ctx.female ? 1 : 0] : l));
    const made = ready ? lines.filter((l) => { try { return ready(l); } catch (_) { return false; } }) : [];
    return pickFrom(made.length ? made : lines, rng);
}

/** The words a person of this kind may need in advance (made in his voice): the acks and the commonest refusals. */
export function commandPool(role, ctx = {}) {
    const k = kindOf(role, ctx);
    const out = new Set();
    const add = (l) => out.add(Array.isArray(l) ? l[ctx.female ? 1 : 0] : l);
    (COMMAND_ACKS[k] || COMMAND_ACKS.civ).slice(0, 3).forEach(add);
    for (const key of ['notWizard', 'rank', 'peaceful']) (REASONS[key][k] || REASONS[key].civ || []).slice(0, 1).forEach(add);
    return [...out];
}

const SING = {
    knight: ['Эй, на стенах стража встала, ночь темна, а меч остёр! За короля, за честь, за славу — не уступим ни на шаг!', 'Налей, налей, пока горит заря, мы за короля и за стены замка!'],
    merchant: ['Хлеб румяный, сыр душистый, ходит торг от дня до дня! Подходи ко мне, прохожий, не пройдёшь ты мимо меня!'],
    builder: ['Камень на камень, брус на брус — стены встанут, я не трус! Раз-два, взяли, ещё взяли!'],
    farmer: ['Ой, да в поле колосится рожь густая, золотая, а мы жнём её, поём, хлеб в закромах и на столе!'],
    wiz: ['Звёзды падают на башню, шепчет ветер заклинанья… Нет, не буду петь — я только пробую.'],
    sea: ['Йо-хо-хо, и бутылка рому! Ветер в парус, волны гонят нас к чужому берегу!'],
    adv: ['Тише, тише… Король спит, а совет не дремлет.'],
};
const JOKES = {
    knight: ['Знаешь, почему рыцарь не боится зомби? Потому что у него уже есть опыт — с тёщей.', 'Рыцарь возвращается домой, а жена спрашивает: «Где щит?» — «Дракон забрал». — «А меч?» — «Он тоже договорился».'],
    adv: ['Король спрашивает: «Что говорит народ?» — «Народ молчит, Ваше Величество». — «Это хороший знак?» — «Для вас — да».'],
    sea: ['Почему пираты не могут выучить алфавит? Потому что они вечно застревают на букве «Р».'],
    wiz: ['Сколько магов нужно, чтобы зажечь факел? Ни одного — но обязательно найдётся трое, которые сожгут башню.'],
    civ: ['Купец приходит к кузнецу: «Сделай мне меч, который никогда не затупится». — «Хорошо. Тогда это будет палка».', 'Фермер хвастался: «У меня корова самая умная». — «Почему?» — «Утром сама просится на выпас, вечером сама просится домой, а в обед — на налоги».'],
};

/** What he says to a talk-command that needs no walking (ask_hp, ask_sees, ask_role, sing, joke, no_items…). */
export function sayReply(kind, ctx = {}, rng = Math.random) {
    const k = kindOf(ctx.role, ctx);
    switch (kind) {
        case 'hp': {
            const f = ctx.hpRatio == null ? 1 : ctx.hpRatio;
            if (f >= 0.95) return pickFrom(k === 'knight' ? ['Цел и невредим!', 'Ни царапины. Готов к службе!'] : ['Я в порядке, спасибо.', 'Цел и здоров.', 'Всё хорошо.'], rng);
            if (f >= 0.6) return pickFrom(['Немного помят, но держусь.', 'Царапины. Жить буду.', 'Пара ран, ничего серьёзного.'], rng);
            if (f >= 0.3) return pickFrom(['Мне досталось, если честно.', 'Ранен… но стою.', 'Больно, но пока держусь.'], rng);
            return pickFrom(['Я едва стою…', 'Мне очень плохо, помоги!', 'Ранен тяжело…'], rng);
        }
        case 'sees': {
            const z = ctx.zombies || 0, n = ctx.nearby || 0;
            if (ctx.danger || z > 0) return pickFrom([`Вижу нежить — ${z > 1 ? 'их несколько' : 'одна'}! Будьте осторожны.`, 'Опасность рядом, держитесь!', 'Зомби поблизости, нужно быть начеку.'], rng);
            if (n > 1) return pickFrom(['Вижу людей рядом, всё спокойно.', 'Вокруг свои, никакой угрозы.', 'Тихо, только люди ходят.'], rng);
            return pickFrom(k === 'knight' ? ['Всё спокойно. Врагов не видно.', 'Тихо. Стража на постах.'] : ['Вроде тихо.', 'Ничего особенного.', 'Всё мирно, слава богам.'], rng);
        }
        case 'role': return ctx.roleLine || 'Живу здесь, помогаю как могу.';
        case 'sing': return pickFrom(SING[k === 'civ' ? ctx.role || 'farmer' : k] || SING.farmer, rng);
        case 'joke': return pickFrom(JOKES[k] || JOKES.civ, rng);
        case 'no_items': return pickFrom((REASONS.noItems[k] || REASONS.noItems.civ), rng);
        case 'no_take': return pickFrom(['Спасибо, но брать не буду — своё несу.', 'Не надо, оставь себе.', 'Мне чужого не нужно.'], rng);
        case 'no_drop': return pickFrom(['Нечего мне класть.', 'У меня в руках пусто.', 'Ронять нечего.'], rng);
        case 'no_bring': return pickFrom(k === 'knight' ? ['Я на посту, носить не обучен.', 'Посыльным я не служу.'] : ['Сейчас не могу, у меня свои дела.', 'Носить — не моя забота.'], rng);
        case 'no_pick': return pickFrom(['Руки заняты, не стану ничего поднимать.', 'Чужое не подбираю.'], rng);
        case 'no_door': return pickFrom((REASONS.noDoor[k] || REASONS.noDoor.civ), rng);
        case 'no_light': return pickFrom((REASONS.noLight[k] || REASONS.noLight.civ), rng);
        case 'no_break': return pickFrom((REASONS.noBreak[k] || REASONS.noBreak.civ), rng);
        case 'no_build': return pickFrom((REASONS.notBuilder[k] || REASONS.notBuilder.civ), rng);
        case 'no_horse': return pickFrom((REASONS.noHorse[k] || REASONS.noHorse.civ), rng);
        case 'no_fly': return pickFrom((REASONS.cantFly[k] || REASONS.cantFly.civ), rng);
        case 'no_shoot': return pickFrom(k === 'knight' ? ['Лука при мне нет — только меч.', 'Я мечник, не лучник.'] : k === 'sea' ? ['Пушки — дело капитана: скажи ему «пли».'] : ['Я не стрелок.', 'Стрелять? Я и лука-то в руках не держал.'], rng);
        default: return 'Хм.';
    }
}

/** A fighter's line when he refuses a spar with someone: a king, a civilian, a friend. */
export const SPAR_REFUSALS = {
    civilian: ['Драться с мирным? Нет, это не по чести.', 'Он безоружен — не стану.'],
    king: ['Поднять меч на короля? Никогда!'],
    far: ['Он слишком далеко, не дотянуться.'],
    self: ['С самим собой драться не стану.'],
    none: ['С кем драться-то? Покажи рукой или назови по имени.', 'Не понял, на кого вы показываете.'],
    noone: ['Нас тут только один — не с кем тренироваться.', 'Мне не с кем сразиться, нужно ещё хоть одного рыцаря.'],
};

/** Where each member of a formation stands: pure (tests). `center` {x,z}; `yaw` the way the leader faces (forward = (−sin, −cos)). */
export function formationSlots(kind, n, center, yaw, gap = 2.6) {
    const fx = -Math.sin(yaw), fz = -Math.cos(yaw); // forward
    const rx = -fz, rz = fx; // right (forward rotated −90°… in x/z: (fz?)) — kept symmetric, only the spread matters
    const out = [];
    const at = (a, f, r, face) => out.push({ x: center.x + fx * f + rx * r, z: center.z + fz * f + rz * r, yaw: face });
    if (kind === 'circle') {
        const rad = Math.max(3.5, (n * gap) / (2 * Math.PI));
        for (let i = 0; i < n; i++) {
            const a = (i / n) * Math.PI * 2;
            const x = center.x + Math.cos(a) * rad, z = center.z + Math.sin(a) * rad;
            out.push({ x, z, yaw: Math.atan2(-(x - center.x), -(z - center.z)) + Math.PI }); // (face out, away from the middle)
        }
        return out;
    }
    const back = yaw + Math.PI; // (they face the leader, who is behind them: the same way he looks to the front → toward him = back)
    if (kind === 'column') {
        for (let i = 0; i < n; i++) at(i, -gap * (i + 1), 0, yaw);
        return out;
    }
    if (kind === 'wedge') {
        for (let i = 0; i < n; i++) { const row = Math.ceil(i / 2), side = i === 0 ? 0 : i % 2 ? -1 : 1; at(i, gap * 3 - row * gap, side * row * gap * 0.9, back); }
        return out;
    }
    if (kind === 'two') {
        const per = Math.ceil(n / 2);
        for (let i = 0; i < n; i++) { const row = i < per ? 0 : 1, k = row ? i - per : i; const m = row ? n - per : per; at(i, gap * 3 + row * gap, (k - (m - 1) / 2) * gap, back); }
        return out;
    }
    // line / shields: a rank in front of the speaker, faces him
    const g = kind === 'shields' ? gap * 0.7 : gap;
    for (let i = 0; i < n; i++) at(i, gap * 3, (i - (n - 1) / 2) * g, back);
    return out;
}

/**
 * Who, of the villagers near, is meant by the scope words. `list`: [{id, x, z, d}] (d: m from me), `me`: {x, z, yaw}.
 * 'none' → the one addressed alone (list[0] is that one). Always a few at most (`max`).
 */
export function pickGroup(scope, list, me, max = 10) {
    if (!list.length) return [];
    const byD = [...list].sort((a, b) => a.d - b.d);
    const fx = -Math.sin(me.yaw), fz = -Math.cos(me.yaw);
    const side = (v) => (v.x - me.x) * -fz + (v.z - me.z) * fx; // + right of my look, − left
    switch (scope.kind) {
        case 'all': return byD.slice(0, max);
        case 'n': return byD.slice(0, Math.min(max, scope.n));
        case 'left': return [[...byD].sort((a, b) => side(a) - side(b))[0]];
        case 'right': return [[...byD].sort((a, b) => side(b) - side(a))[0]];
        case 'nearest': return [byD[0]];
        case 'rest': return byD.slice(1, max);
        default: return [list[0]];
    }
}

/**
 * Resolves a pointed / named / sided target among candidates `c` ({id, x, z, d, name}) from my eye and look.
 * `ray`: {o:{x,y,z}, d:{x,y,z}} the pointing hand's (or the gaze's) ray. A cone of `maxAng` rad.
 */
export function pickTarget(target, c, me, ray = null, maxAng = 0.28) {
    if (!c.length) return null;
    if (target.ref === 'name') {
        const n = normalize(target.name);
        return c.find((v) => normalize(v.name || '') === n || (v.name && normalize(v.name).startsWith(n.slice(0, Math.max(3, n.length - 1))))) || null;
    }
    if (target.ref === 'left' || target.ref === 'right' || target.ref === 'nearest') return pickGroup({ kind: target.ref }, c, me)[0] || null;
    if (target.ref === 'other') return [...c].sort((a, b) => a.d - b.d)[0] || null;
    if (!ray) return null;
    let best = null, ba = maxAng;
    for (const v of c) {
        const dx = v.x - ray.o.x, dy = (v.y ?? ray.o.y) - ray.o.y, dz = v.z - ray.o.z;
        const len = Math.hypot(dx, dy, dz) || 1;
        const cos = (ray.d.x * dx + ray.d.y * dy + ray.d.z * dz) / len;
        const ang = Math.acos(Math.max(-1, Math.min(1, cos)));
        // (a man across a yard is narrower on the sky: the cone shrinks with the distance, but never below 0.07)
        const lim = Math.max(0.07, Math.min(maxAng, Math.atan2(1.1, Math.max(1, len))));
        if (ang < lim && ang < ba) { ba = ang; best = v; }
    }
    return best;
}
